query:
process
where event.type == "start"
and (
  /* Windows offensive recon tooling */
  (
    host.os.type == "windows" and
    (
      process.command_line regex "(?i)(winpeas|seatbelt|sharpup|watson|itm4nprivesc|azurestealth)"
      or process.command_line regex "(?i)invoke-(seatbelt|sharpup|watson)"
      or process.command_line regex "(?i)gathernetworkinfo|rbcd-check"
    )
  )

  or

  /* Linux privilege & environment discovery frameworks */
  (
    host.os.type == "linux" and
    process.command_line regex "(?i)(linpeas|lse\\.sh|pspy|linux-exploit-suggester)"
  )

  or

  /* macOS recon & security bypass discovery */
  (
    host.os.type == "macos" and
    process.command_line regex "(?i)(linpeas|osx-recon|csrutil\\s+status)"
  )
)

process
where event.type == "start"
and
(
  /* Windows CMD directory enumeration */
  (
    process.name == "cmd.exe" and
    process.command_line like "*dir *" or
    process.command_line like "*tree *"
  )

  or

  /* Windows PowerShell recursive enumeration */
  (
    process.name in ("powershell.exe", "pwsh.exe") and
    process.command_line like "*Get-ChildItem*" and
    process.command_line like "*-Recurse*"
  )

  or

  /* PowerShell short aliases */
  (
    process.name in ("powershell.exe", "pwsh.exe") and
    process.command_line like "*gci *-recurse*" or
    process.command_line like "*ls *-recurse*"
  )

  or

  /* Linux / macOS file discovery */
  (
    process.name in ("find", "ls", "locate") and
    (
      process.command_line like "*find *-type f*" or
      process.command_line like "*ls -R*" or
      process.command_line like "*locate *"
    )
  )

  or

  /* Network / mount discovery */
  (
    process.name == "findmnt" and
    process.command_line like "*-t nfs*"
  )

  or

  /* Known directory listing tools */
  (
    process.name == "DirLister.exe"
  )
)

sequence by host.id with maxspan=15m

  /* Stage 1: Interactive or orchestration context */
  [process where
    (
      /* Windows */
      (host.os.type == "windows" and process.name == "cmd.exe") or

      /* Linux */
      (host.os.type == "linux" and process.name in ("sh", "bash")) or

      /* Containers / Kubernetes */
      (process.name == "kubectl")
    )
  ]

  /* Stage 2: at job submission */
  [process where
    (
      /* Windows at.exe */
      (host.os.type == "windows" and process.name == "at.exe") or

      /* Linux at */
      (host.os.type == "linux" and process.name == "at")
    )
  ]

process
where host.os.type == "windows" and
(
  /* Classic reg.exe queries */
  process.name in ("reg.exe", "cmd.exe") and
  process.command_line like "*reg query*"

  or

  /* PowerShell cmdlets querying registry */
  process.name == "powershell.exe" and
  (process.command_line like "*Get-Item*" or process.command_line like "*Get-ChildItem*")

  or

  /* COM object enumeration via HKCR */
  process.name == "powershell.exe" and process.command_line like "*HKCR:\\CLSID*"

  or

  /* AlwaysInstallElevated check */
  process.command_line like "*AlwaysInstallElevated*"

  or

  /* Software Inventory Logging (SIL) status check */
  process.command_line like "*SoftwareInventoryLogging*"

  or

  /* SystemStartOptions query */
  process.command_line like "*SystemStartOptions*"
)

/* Rule Name: User Crontab Modification via Shell */
sequence by host.id with maxspan=10m
  [process where
    host.os.type in ("linux", "macos") and
    process.name in ("sh", "bash", "zsh")
  ]
  [process where
    host.os.type in ("linux", "macos") and
    process.name == "crontab"
  ]

/* Rule Name: Scheduled Task Imported from XML Definition */
sequence by host.id with maxspan=10m
  [process where
    host.os.type == "windows" and
    process.name in ("powershell.exe", "schtasks.exe")
  ]
  [process where
    host.os.type == "windows" and
    process.args : (".xml", "RegisterByXml")
  ]

process
where
(
  /* Windows ping-based internet connectivity checks */
  host.os.type == "windows" and
  process.name == "ping.exe"
)
or
(
  /* Linux / macOS ping-based connectivity checks */
  host.os.type in ("linux", "macos") and
  process.name == "ping"
)
or
(
  /* PowerShell Test-NetConnection (ICMP and TCP checks) */
  host.os.type == "windows" and
  process.name == "powershell.exe" and
  process.command_line like "*Test-NetConnection*"
)

process
where
(
  /* Windows native discovery */
  host.os.type == "windows" and
  (
    process.name in ("tasklist.exe", "wmic.exe", "taskmgr.exe")
    or
    (
      process.name == "powershell.exe" and
      process.command_line like "*Get-Process*"
    )
    or
    (
      process.name == "cmd.exe" and
      process.command_line like "*tasklist*"
    )
  )
)
or
(
  /* Linux & macOS discovery */
  host.os.type in ("linux", "macos") and
  process.name == "ps"
)
or
(
  /* High-risk process enumeration tools */
  process.name in ("ProcessHacker.exe", "PChunter64.exe")
)

process
where host.os.type == "windows"
and (
  /* Local WMI process execution */
  (process.name == "wmic.exe" and process.args : ("call create")) or

  /* Remote WMI execution */
  (process.name == "wmic.exe" and process.args : ("/node:")) or

  /* PowerShell WMI execution (including encoded) */
  (process.name == "powershell.exe" and
   process.args : ("Invoke-WmiMethod", "-EncodedCommand")) or

  /* DLL execution via WMI */
  (process.name == "rundll32.exe" and
   process.args : (".dll"))
)
